// count numbers in [L,R] with property P
ll go(int pos, int tight, int leadZero /*+ extra state*/){
    if (pos == len) return valid();
    int limit = tight ? digitsN[pos] : 9;
    ll res = 0;
    for (int d = 0; d <= limit; d++)
        res += go(pos + 1, tight && d == limit, leadZero && d == 0, update(d));
    return memo[...] = res;
}   // call: f(R) - f(L-1)
